"""Complete authorized event checks; only the separate recorder writes event ledgers."""
import json,hashlib,math,re
from datetime import datetime,timezone,timedelta
from collections import defaultdict
from bkn_osdk import kn

TARGET='ecommerce_ops_zh_cn'
VERSION='ecommerce-events-1.0.0'
TZ=timezone(timedelta(hours=8))
SPEC={
 'purchase_expected_receipt_gap':('purchase_order','po_id',None,None),
 'payment_failure_unrecovered':('order','order_id','quiet_wait_minutes',60),
 'logistics_tracking_stalled':('shipment','shipment_id','stagnation_hours',3600),
 'return_received_processing_wait':('after_sales_case','case_id','processing_wait_hours',3600)}
def dt(v):
    if v is None or v=='':return None
    if not isinstance(v,str):raise ValueError('Invalid source date/time')
    x=datetime.fromisoformat(v.replace('Z','+00:00'))
    return x.replace(tzinfo=TZ) if x.tzinfo is None else x.astimezone(TZ)
def positive(v):
    if isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or v<=0:raise ValueError('Threshold must be finite and positive')
    return v
def policy_version(code,rule):
    basis={'version':VERSION,'event_type':code,'criteria_version':rule['criteria_version'],'thresholds':rule.get('thresholds',{})}
    return 'ev1_'+hashlib.sha256(json.dumps(basis,sort_keys=True,separators=(',',':')).encode()).hexdigest()[:12]
def attributes(values):
    out={}
    for key,value in values.items():
        if value is None:continue
        text=json.dumps(value,ensure_ascii=False,separators=(',',':')) if isinstance(value,(dict,list)) else str(value)
        if len(text)>250:
            text='sha256:'+hashlib.sha256(text.encode()).hexdigest()
            label='证据列表较长，请通过主体关系读取完整业务明细'
        else:label=text
        out[key]={'key':text,'label':label}
    if len(out)>64:raise ValueError('Too many event attributes')
    return out
def hit(key,name,values):return {'key':str(key),'name':str(name or key),'attributes':attributes(values)}

class Check:
    def __init__(self,event):
        if not isinstance(event,dict) or set(event)-{'kn_id','event_type','as_of','preview_threshold'}:raise ValueError('Unsupported event check input')
        if event.get('kn_id')!=TARGET:raise ValueError('This recorder is scoped to the repair copy')
        self.code=event.get('event_type')
        if self.code not in SPEC:raise ValueError('Unsupported event type')
        self.ctx=kn.resolve_context();self.base='/api/bkn-backend/v1/knowledge-networks/'+TARGET
        self.definition=self.request(self.base+'/event-types/'+self.code)
        self.rule=self.definition.get('rule') or {}
        if self.definition.get('source')!='rule' or self.definition.get('rule_tool') is not None:raise ValueError('Expected an application-checked rule event type')
        if self.definition.get('subject')!=SPEC[self.code][0]:raise ValueError('Event subject does not match detector contract')
        if self.rule.get('detector_version')!=VERSION or self.rule.get('criteria_version')!=1:raise ValueError('Unsupported rule contract version')
        self.version=policy_version(self.code,self.rule)
        self.eligible=self.rule.get('activation_state')=='ready_for_application_check' and self.rule.get('approved') is True and self.definition.get('rule_version')==self.version
        self.now=datetime.now(TZ);self.asof=dt(event.get('as_of')) or self.now
        if 'as_of' in event:self.eligible=False
        parameter=SPEC[self.code][2];factor=SPEC[self.code][3];self.threshold=None
        if parameter:
            value=self.rule.get('thresholds',{}).get(parameter)
            if 'preview_threshold' in event:value=event['preview_threshold'];self.eligible=False
            if value is None:raise ValueError('Event threshold has not been configured')
            self.threshold=positive(value);self.seconds=self.threshold*factor
        elif 'preview_threshold' in event:raise ValueError('This event has no duration threshold')
        self.calls=[];self.unknown=[];self.covered=[];self.hits=[]
        model=self.request(self.base,query={'mode':'export'});self.objects={x['id']:x for x in model['object_types']}
    def request(self,path,body=None,query=None):
        return kn.request(self.ctx,path,method='POST' if body is not None else 'GET',body=body,query=query,timeout=25)
    def table(self,oid):
        s=self.objects[oid]['data_source']
        if s['type']!='resource' or not re.fullmatch(r'[A-Za-z0-9_-]+',s['id']):raise ValueError('Invalid resource binding')
        return '{{'+s['id']+'}}'
    def scan(self,sql,name):
        rows=[]
        for offset in range(0,250000,5000):
            result=self.request('/api/vega-backend/v1/resources/query',{'query':sql,'query_format':'sql','paging':{'mode':'single','limit':5000,'offset':offset}})
            if not isinstance(result,dict) or not isinstance(result.get('entries'),list) or result.get('warnings'):raise ValueError('Incomplete source query: '+name)
            batch=result['entries'];rows.extend(batch)
            if len(batch)<5000:
                self.calls.append({'source':name,'rows':len(rows),'pages':offset//5000+1});return rows
        raise ValueError('Source scan reached the safety bound; no partial check is submitted')
    def rows(self,oid,fields,key):
        rows=self.scan('SELECT '+','.join(fields)+' FROM '+self.table(oid)+' ORDER BY '+key,oid)
        if len({r[key] for r in rows})!=len(rows):raise ValueError('Duplicate source identity: '+oid)
        return rows
    def skip(self,key,reason):self.unknown.append({'key':str(key),'reason':reason})
    def cover(self,key):self.covered.append(str(key))
    def purchase(self):
        pos=self.rows('purchase_order',['po_id','po_no','supplier_id','warehouse_id','order_status','expected_date'],'po_id')
        items=self.rows('purchase_order_item',['item_id','po_id','sku_id','quantity','received_qty'],'item_id')
        inbound=self.scan('SELECT po_item_id,SUM(quantity) AS qty FROM '+self.table('inbound_record')+' GROUP BY po_item_id ORDER BY po_item_id','inbound_record_by_item')
        received={r['po_item_id']:int(r['qty'] or 0) for r in inbound};by=defaultdict(list)
        for i in items:by[i['po_id']].append(i)
        for p in pos:
            key=p['po_id'];lines=by[key]
            if not lines or any(int(i['received_qty'])!=received.get(i['item_id'],0) for i in lines):self.skip(key,'采购明细缺失或收货快照与入库汇总不一致');continue
            if p['order_status'] in {'completed','cancelled'}:self.cover(key);continue
            expected=dt(p['expected_date'])
            if expected is None:self.skip(key,'缺少预计到货日，不能判断超期或恢复');continue
            missing=[i for i in lines if received.get(i['item_id'],0)<int(i['quantity'])]
            self.cover(key)
            if expected.date()<self.asof.date() and missing:
                self.hits.append(hit(key,p['po_no'],{'expected_date':expected.date().isoformat(),'incomplete_line_count':len(missing),'purchase_item_ids':[i['item_id'] for i in missing],'supplier_id':p['supplier_id'],'warehouse_id':p['warehouse_id'],'check_date':self.asof.date().isoformat(),'receipt_basis':'入库记录按采购明细汇总，并与收货快照核对'}))
    def payment(self):
        orders=self.rows('order',['order_id','order_no','order_status','payment_time','cancel_time','complete_time'],'order_id')
        attempts=self.rows('payment_attempt',['attempt_id','order_id','attempt_no','channel','status','attempted_at','settled_at','failure_code'],'attempt_id')
        payments=self.scan('SELECT DISTINCT order_id FROM '+self.table('payment')+' WHERE paid_at IS NOT NULL ORDER BY order_id','confirmed_payment_orders')
        paid={r['order_id'] for r in payments};by=defaultdict(list)
        for a in attempts:by[a['order_id']].append(a)
        for o in orders:
            key=o['order_id']
            if o['cancel_time'] or o['complete_time'] or o['payment_time'] or key in paid:self.cover(key);continue
            rs=by[key]
            if not rs:self.cover(key);continue
            if len({a['attempt_no'] for a in rs})!=len(rs) or any(not a['attempted_at'] for a in rs):self.skip(key,'支付尝试序号重复或缺少时间');continue
            rs=sorted([a for a in rs if dt(a['attempted_at'])<=self.asof],key=lambda a:a['attempt_no'])
            if not rs:self.cover(key);continue
            if any(dt(y['attempted_at'])<dt(x['attempted_at']) for x,y in zip(rs,rs[1:])):self.skip(key,'支付尝试序号与时间顺序矛盾');continue
            if any(a['status']=='success' and a['settled_at'] and dt(a['settled_at'])<=self.asof for a in rs):self.cover(key);continue
            if any(a['status'] not in {'failed','success'} or a['status']=='success' and not a['settled_at'] for a in rs):self.skip(key,'支付尝试仍进行中或成功结算时间不明');continue
            first,last=rs[0],rs[-1];self.cover(key)
            if first['status']=='failed' and last['status']=='failed' and o['order_status']=='pending_payment':
                wait=(self.asof-dt(last['attempted_at'])).total_seconds()
                if wait>=self.seconds:self.hits.append(hit(key,o['order_no'],{'first_failed_at':first['attempted_at'],'last_failed_at':last['attempted_at'],'attempt_count':len(rs),'last_channel':last['channel'],'failure_code':last['failure_code'],'quiet_wait_minutes':self.threshold,'elapsed_minutes':round(wait/60,2),'threshold_crossed_at':(dt(last['attempted_at'])+timedelta(seconds=self.seconds)).isoformat()}))
    def logistics(self):
        ships=self.rows('shipment',['shipment_id','shipment_no','order_id','shipment_status','express_company','warehouse_id','shipped_at'],'shipment_id')
        cutoff="'"+self.asof.strftime('%Y-%m-%d %H:%M:%S.%f')+"'"
        sql="SELECT shipment_id,MAX(tracked_at) AS last_node,MAX(CASE WHEN tracking_status IN ('已签收','已退回','取消发货') THEN tracked_at END) AS last_terminal,MAX(CASE WHEN tracking_status NOT IN ('已签收','已退回','取消发货') THEN tracked_at END) AS last_nonterminal FROM "+self.table('logistics_tracking')+' WHERE tracked_at<='+cutoff+' GROUP BY shipment_id ORDER BY shipment_id'
        nodes=self.scan(sql,'logistics_latest_times');by={r['shipment_id']:r for r in nodes}
        for s in ships:
            key=s['shipment_id']
            if s['shipment_status'] in {'signed','delivered','returned','cancelled'}:self.cover(key);continue
            sent=dt(s['shipped_at'])
            if sent is None:
                if s['shipment_status']=='in_transit':self.skip(key,'在途发货单缺少实际发货时间')
                else:self.cover(key)
                continue
            if sent>self.asof:self.cover(key);continue
            n=by.get(key);last=dt(n['last_node']) if n else sent;terminal=dt(n['last_terminal']) if n else None;other=dt(n['last_nonterminal']) if n else None
            if terminal and other and terminal==other:self.skip(key,'同一最新时间存在终态与非终态，需要核对节点顺序');continue
            self.cover(key)
            if terminal and terminal>=last:continue
            wait=(self.asof-last).total_seconds()
            if wait>=self.seconds:self.hits.append(hit(key,s['shipment_no'],{'order_id':s['order_id'],'carrier':s['express_company'],'warehouse_id':s['warehouse_id'],'shipped_at':s['shipped_at'],'last_tracking_at':n['last_node'] if n else None,'reason_code':'tracking_stalled' if n else 'no_tracking_after_shipment','stagnation_hours':self.threshold,'elapsed_hours':round(wait/3600,2),'threshold_crossed_at':(last+timedelta(seconds=self.seconds)).isoformat()}))
    def aftersales(self):
        rows=self.rows('after_sales_case',['case_id','order_id','business_type','status','requested_amount','approved_amount','requested_at','return_received_at','completed_at'],'case_id')
        for r in rows:
            key=r['case_id']
            if r['business_type']!='return_refund' or r['completed_at']:self.cover(key);continue
            received=dt(r['return_received_at'])
            if received is None:
                if r['status']=='received':self.skip(key,'已收货状态缺少收货时间')
                else:self.cover(key)
                continue
            self.cover(key);wait=(self.asof-received).total_seconds()
            if wait>=self.seconds:self.hits.append(hit(key,'售后单 '+str(key),{'order_id':r['order_id'],'business_type':r['business_type'],'case_status':r['status'],'return_received_at':r['return_received_at'],'requested_amount':r['requested_amount'],'approved_amount':r['approved_amount'],'processing_wait_hours':self.threshold,'elapsed_hours':round(wait/3600,2),'threshold_crossed_at':(received+timedelta(seconds=self.seconds)).isoformat(),'amount_basis':'申请及批准金额不等于退款已到账'}))
    def run(self):
        {'purchase_expected_receipt_gap':self.purchase,'payment_failure_unrecovered':self.payment,'logistics_tracking_stalled':self.logistics,'return_received_processing_wait':self.aftersales}[self.code]()
        if len({h['key'] for h in self.hits})!=len(self.hits) or len(self.hits)>20000:raise ValueError('Ambiguous or oversized event hit set')
        if not {h['key'] for h in self.hits}<=set(self.covered):raise ValueError('Hit is outside the successful decision coverage')
        message=(str(len(self.unknown))+'个主体无法判断，未纳入恢复范围') if self.unknown else ''
        payload={'event_type':self.code,'rule_version':self.version,'status':'ok','message':message,'hits':self.hits,'covered':self.covered}
        if len(json.dumps(payload,ensure_ascii=False).encode())>15*1024*1024:raise ValueError('Event check payload exceeds safe body size')
        return {'status':'complete','read_only':True,'event_type':self.code,'rule_version':self.version,'source_read_complete':True,'submission_eligible':self.eligible,'as_of':self.asof.isoformat(),'threshold':self.threshold,'hit_count':len(self.hits),'covered_count':len(self.covered),'unassessed_count':len(self.unknown),'unassessed':self.unknown,'calls':self.calls,'rule_check_input':payload,'basis':'完整授权源表扫描；covered限定可判定范围；未判定对象不自动恢复。首次命中由事件模块标记backlog。'}

def detect(event):return Check(event).run()
def record(event):
    if not isinstance(event,dict) or set(event)-{'kn_id','event_type'}:raise ValueError('Recorder accepts only target network and event type; thresholds come from approved server policy')
    check=Check(event)
    if not check.eligible:raise ValueError('Event policy is not approved or its version does not match')
    try:
        result=check.run();payload=result['rule_check_input']
    except Exception as error:
        # Reading failures never become an empty successful check.
        payload={'event_type':check.code,'rule_version':check.version,'status':'unknown','message':('源读取或判定失败：'+str(error))[:400],'hits':[]}
        recorded=check.request(check.base+'/rule-checks',payload)
        return {'status':'unknown','read_only':False,'event_type':check.code,'source_business_writes':False,'recorded_check':recorded.get('check'),'error':payload['message']}
    recorded=check.request(check.base+'/rule-checks',payload)
    return {'status':'complete','read_only':False,'source_business_writes':False,'event_type':check.code,'hit_count':result['hit_count'],'covered_count':result['covered_count'],'unassessed_count':result['unassessed_count'],'rule_version':check.version,'recorded_check':recorded.get('check'),'events':[{'id':e['id'],'object_key':e['object_key'],'status':e['status'],'backlog':e['backlog']} for e in recorded.get('events',[])],'basis':'仅写当前修复副本事件台账及变更记录，不修改业务源表、不发送消息。'}


def handler(event):
    return detect(event)

