            timeline.append({'log_id':r['log_id'],'from_status':r['from_status'],'to_status':state,'time':dt.isoformat(),'operator_type':r['operator_type'],'operator_id':r['operator_id']})
        h=elapsed(paid,shipped)
        if h is not None and b.inside(shipped):durations.append(h)
        waiting=elapsed(entered,b.cutoff) if state not in {'completed','cancelled','refunded'} else None
        if b.start and not any(b.inside(moment(x['time'])) for x in timeline):continue
        details.append({'order_id':oid,'state_at_cutoff':state,'current_state_wait_hours':waiting,'attention':waiting>threshold if waiting is not None and threshold is not None else None,'paid_to_first_ship_hours':h,'episodes':episodes,'timeline':timeline,'sequence_gaps':gaps})
    return b.result('order_journey',[metric('M01','付款至首次发货平均耗时',average(durations),'h',sample_size=len(durations),time_basis='首次发货时间'),metric('M02','付款后待发货阶段取消订单数',len(cancelled),time_basis='取消迁移时间'),metric('M03','已发货阶段转入退款订单数',len(refunds),time_basis='转入退款迁移时间')],details,excluded_duplicate_events=duplicates,ignored_same_state_events=noops,wait_threshold_hours=threshold)

def logistics(e):
    b=Biz(e);b.scope('order_ids','shipment_ids');threshold=b.threshold('stagnation_hours')
    f=[in_filter('s.order_id',ids(e,'order_ids')),in_filter('s.shipment_id',ids(e,'shipment_ids'))]
    carriers=e.get('carriers',[])
    if not isinstance(carriers,list) or len(carriers)>50 or any(not isinstance(x,str) for x in carriers):raise ValueError('carriers must be a string array')
    if carriers:f.append('s.express_company IN ('+','.join(literal(x) for x in carriers)+')')
    rows=b.scan('SELECT s.shipment_id,s.order_id,s.express_company,s.warehouse_id,s.shipped_at,t.tracking_id,t.tracking_status,t.tracked_at,t.location,t.description FROM '+b.table('shipment')+' s LEFT JOIN '+b.table('logistics_tracking')+' t ON s.shipment_id=t.shipment_id'+where(f)+' ORDER BY s.shipment_id,t.tracked_at,t.tracking_id')
    groups=defaultdict(list)
    for r in rows:
        if moment(r['shipped_at']) is not None and moment(r['shipped_at'])<=b.cutoff:groups[r['shipment_id']].append(r)
    details=[];hours=[];bycarrier=defaultdict(list);open_count=0;bad=0
    for sid,rs in groups.items():
        nodes=[r for r in rs if r['tracked_at'] and moment(r['tracked_at'])<=b.cutoff]
        pickup=next((moment(r['tracked_at']) for r in nodes if r['tracking_status']=='已揽件'),None)
        signed=next((moment(r['tracked_at']) for r in nodes if r['tracking_status']=='已签收'),None)
        h=elapsed(pickup,signed);latest=nodes[-1] if nodes else None;status=latest['tracking_status'] if latest else '无轨迹'
        terminal=status in {'已签收','已退回','取消发货'}
        since=elapsed(moment(latest['tracked_at']) if latest else moment(rs[0]['shipped_at']),b.cutoff)
        if pickup and signed and h is None:bad+=1
        if h is not None and b.inside(signed):hours.append(h);bycarrier[rs[0]['express_company']].append(h)
        if not terminal:open_count+=1
        if b.start and not any(b.inside(moment(r['tracked_at'])) for r in nodes):continue
        details.append({'shipment_id':sid,'order_id':rs[0]['order_id'],'carrier':rs[0]['express_company'],'warehouse_id':rs[0]['warehouse_id'],'status':status,'pickup_at':pickup.isoformat() if pickup else None,'signed_at':signed.isoformat() if signed else None,'transport_hours':h,'hours_since_last_update':since,'attention':(since>threshold and not terminal) if since is not None and threshold is not None else None,'timeline':[{'tracking_id':r['tracking_id'],'status':r['tracking_status'],'time':r['tracked_at'],'location':r['location']} for r in nodes]})
    return b.result('logistics',[metric('M04','揽收至签收平均耗时',average(hours),'h',sample_size=len(hours),time_basis='首次签收时间')],details,open_shipments=open_count,invalid_time_pairs=bad,by_carrier=[{'carrier':k,'sample_size':len(v),'avg_hours':average(v)} for k,v in bycarrier.items()],stagnation_hours=threshold)

def cart_demand(e):
