def payment_retry(e):
    b=Biz(e);b.scope('order_ids')
    rows=b.scan('SELECT attempt_id,order_id,attempt_no,channel,status,amount,attempted_at,settled_at,failure_code FROM '+b.table('payment_attempt')+where([in_filter('order_id',ids(e,'order_ids'))])+' ORDER BY order_id,attempt_no,attempt_id')
    groups=defaultdict(list)
    for r in rows:
        dt=moment(r['attempted_at'])
        if dt and dt<=b.cutoff:groups[r['order_id']].append(r)
    channels=e.get('channels',[]);codes=e.get('failure_codes',[])
    if any(not isinstance(v,list) or len(v)>50 or any(not isinstance(x,str) for x in v) for v in [channels,codes]):raise ValueError('channels and failure_codes must be string arrays')
    total=failed=recovered=0;details=[];bychannel=defaultdict(lambda:{'orders':0,'first_failed':0,'recovered':0});invalid=0
    for oid,rs in groups.items():
        if len({r['attempt_no'] for r in rs})!=len(rs):raise ValueError('Duplicate order/attempt_no; refusing ambiguous first attempt')
        first=rs[0]
        if not b.inside(moment(first['attempted_at'])) or channels and first['channel'] not in channels:continue
        if any(moment(y['attempted_at'])<moment(x['attempted_at']) for x,y in zip(rs,rs[1:])):invalid+=1;continue
        total+=1;isfailed=first['status']=='failed';failed+=int(isfailed)
        successes=[r for r in rs[1:] if r['status']=='success' and (moment(r['settled_at']) or moment(r['attempted_at']))<=b.cutoff]
        success=successes[0] if isfailed and successes else None;recovered+=int(success is not None)
        g=bychannel[first['channel']];g['orders']+=1;g['first_failed']+=int(isfailed);g['recovered']+=int(success is not None)
        if not codes or first['failure_code'] in codes:details.append({'order_id':oid,'first_status':first['status'],'first_channel':first['channel'],'first_failure_code':first['failure_code'],'recovered':success is not None if isfailed else None,'recovery_hours':elapsed(moment(first['attempted_at']),moment(success['settled_at']) or moment(success['attempted_at'])) if success else None,'observation_hours':elapsed(moment(first['attempted_at']),b.cutoff),'attempts':rs})
    return b.result('payment_retry',[metric('M11','首次支付尝试失败率',ratio(failed,total),numerator=failed,denominator=total,time_basis='首次尝试时间'),metric('M12','首次支付失败恢复率',ratio(recovered,failed),numerator=recovered,denominator=failed,time_basis='首次尝试队列，恢复观察至as_of')],details,unrecovered_orders=failed-recovered,invalid_sequence_orders=invalid,by_channel=[dict(channel=k,**v) for k,v in bychannel.items()],detail_failure_code_filter=codes,cohort_note='failure_codes只筛选明细，不缩小首次失败率的分母。')

