        if end is not None and h is None:invalid+=1
        if h is not None and b.inside(end):groups[r['business_type']].append(h)
        # Current outstanding request amount is a snapshot, independent of the completed-event window.
        if end is None and start and start<=b.now:pending+=dec(r['requested_amount']);count+=1
        r['completed_hours']=h;r['current_wait_hours']=elapsed(start,b.now) if end is None else None;r['attention']=r['current_wait_hours']>threshold if r['current_wait_hours'] is not None and threshold is not None else None;details.append(r)
    series=[{'business_type':k,'value':average(v),'sample_size':len(v)} for k,v in groups.items()]
    return b.result('aftersales_timing',[metric('M09','售后平均完成时长',None,'h',status='grouped',group_by=['business_type'],groups=series,time_basis='完成时间'),metric('M10','在办售后申请金额',format(pending,'0.2f'),'CNY',case_count=count,time_basis='当前快照，与完成期间筛选分开')],details,invalid_time_pairs=invalid,amount_note='申请金额不等于批准金额、实际退款现金或确认负债。')


def handler(event):
    if not isinstance(event.get('include_aftersales_timing',True),bool):raise ValueError('include_aftersales_timing must be boolean')
    old_scope=any(event.get(k) for k in ['template_ids','user_id','check_validity','order_ids','case_ids'])
    result=legacy_handler(event) if old_scope else {'status':'complete','domain':'coupon','kn_id':event.get('kn_id'),'read_only':True,'calls':[],'results':{},'warnings':[]}
    if event.get('include_aftersales_timing',True) and (event.get('order_ids') or event.get('case_ids') or event.get('all_data') or event.get('start_time')):
