def positive_ids(value,maximum):
    if not value:return []
    parts=value.split(',')
    if len(parts)>maximum or any(not x.isdigit() or int(x)<=0 for x in parts):
        raise ValueError('IDs must be comma-separated positive integers; maximum '+str(maximum))
    return sorted(set(map(int,parts)))

def legacy_handler(event):
    if not isinstance(event,dict):raise ValueError('Input must be an object')
    def csv_ids(name):
        values=event.get(name) or []
        if not isinstance(values,list):raise ValueError(name+' must be an array')
        result=[]
        for x in values:
            if isinstance(x,bool) or not isinstance(x,(int,float)) or int(x)!=x or x<=0:raise ValueError(name+' must contain positive integer IDs')
            result.append(str(int(x)))
        return ','.join(result)
    for key in ['all_skus','include_offline','check_validity']:
        if key in event and not isinstance(event[key],bool):raise ValueError(key+' must be boolean')
    limit=event.get('detail_limit',20)
    if isinstance(limit,bool) or not isinstance(limit,(int,float)) or int(limit)!=limit:raise ValueError('detail_limit must be an integer')
    args=SimpleNamespace(kn_id=event.get('kn_id'),order_ids=csv_ids('order_ids'),user_ids=csv_ids('user_ids'),sku_ids=csv_ids('sku_ids'),po_item_ids=csv_ids('po_item_ids'),template_ids=csv_ids('template_ids'),case_ids=csv_ids('case_ids'),high_threshold=event.get('high_value_threshold'),medium_threshold=event.get('medium_value_threshold'),all_skus=event.get('all_skus',False),include_offline=event.get('include_offline',False),detail_limit=int(limit),user_id=event.get('user_id'),check_validity=event.get('check_validity',False))
    if not isinstance(args.kn_id,str) or not re.fullmatch('[a-zA-Z0-9_-]{1,100}',args.kn_id):raise ValueError('invalid knowledge network ID')
    try:
