def payment_retry(e):
    b=Biz(e);b.scope('order_ids')
    rows=b.scan('SELECT attempt_id,order_id,attempt_no,channel,status,amount,attempted_at,settled_at,failure_code FROM '+b.table('payment_attempt')+where([in_filter('order_id',ids(e,'order_ids'))])+' ORDER BY order_id,attempt_no,attempt_id')
    groups=defaultdict(list)
