TZ=timezone(timedelta(hours=8))
def moment(v):
    if v is None or v=='':return None
    if not isinstance(v,str):raise ValueError('Date/time must be ISO8601 text')
    d=datetime.fromisoformat(v.replace('Z','+00:00'))
    return d.replace(tzinfo=TZ) if d.tzinfo is None else d.astimezone(TZ)
def dec(v):return Decimal(str(v)) if v is not None else Decimal(0)
def ids(e,k,maximum=1000):
    v=e.get(k,[])
    if not isinstance(v,list) or len(v)>maximum:raise ValueError(k+' must be an array with at most '+str(maximum)+' IDs')
    if any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or int(x)!=x or x<=0 for x in v):raise ValueError(k+' must contain positive integer IDs')
    return sorted(set(map(int,v)))
def literal(v):return "'"+str(v).replace("'","''")+"'"
def in_filter(column,values):return column+' IN ('+','.join(map(str,values))+')' if values else ''
def where(parts):return ' WHERE '+' AND '.join('('+s+')' for s in parts if s) if any(parts) else ''
def metric(code,name,value,unit='1',**kw):return dict(code=code,name=name,value=value,unit=unit,status=kw.pop('status','no_data' if value is None else 'ok'),**kw)
def ratio(n,d):return n/d if d else None
def average(xs):return sum(xs)/len(xs) if xs else None
def elapsed(a,b):return (b-a).total_seconds()/3600 if a is not None and b is not None and b>=a else None

class Biz:
    def __init__(self,e):
        if not isinstance(e,dict):raise ValueError('Input must be an object')
        self.e=e;self.knid=e.get('kn_id')
        if not isinstance(self.knid,str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,100}',self.knid):raise ValueError('kn_id is required')
        self.now=datetime.now(TZ);self.cutoff=moment(e.get('as_of')) or self.now
        self.start=moment(e.get('start_time'));self.end=moment(e.get('end_time'))
        if bool(self.start)!=bool(self.end) or self.start and self.start>=self.end:raise ValueError('Provide a valid start_time/end_time pair')
        if self.end and self.end>self.cutoff:raise ValueError('end_time must not exceed as_of')
        self.limit=e.get('detail_limit',20)
        if isinstance(self.limit,bool) or not isinstance(self.limit,int) or not 0<=self.limit<=100:raise ValueError('detail_limit must be an integer from 0 to 100')
        for k in ['all_data','selected_only']:
            if k in e and not isinstance(e[k],bool):raise ValueError(k+' must be boolean')
        self.calls=[];self.ctx=kn.resolve_context()
        network=self.request('/api/bkn-backend/v1/knowledge-networks/'+self.knid,query={'mode':'export'})
        self.objects={o['id']:o for o in network.get('object_types',[])}
    def request(self,path,body=None,query=None):return kn.request(self.ctx,path,method='POST' if body is not None else 'GET',body=body,query=query,timeout=25)
    def table(self,oid):
        o=self.objects.get(oid);s=(o or {}).get('data_source',{})
        if s.get('type')!='resource' or not re.fullmatch(r'[a-zA-Z0-9_-]+',s.get('id','')):raise ValueError('Missing resource binding: '+oid)
        return '{{'+s['id']+'}}'
    def scan(self,sql):
        rows=[]
        for off in range(0,250000,5000):
            r=self.request('/api/vega-backend/v1/resources/query',{'query':sql,'query_format':'sql','paging':{'mode':'single','limit':5000,'offset':off}})
            if not isinstance(r,dict) or not isinstance(r.get('entries'),list) or r.get('warnings'):raise ValueError('Incomplete or invalid resource response')
            batch=r['entries'];rows.extend(batch)
            if len(batch)<5000:
                self.calls.append({'kind':'resource_sql','query':sql,'rows':len(rows),'pages':off//5000+1});return rows
        raise ValueError('250000-row safety bound reached; no partial totals returned')
    def scope(self,*keys):
        if not self.e.get('all_data') and not self.start and not any(ids(self.e,k) for k in keys):raise ValueError('Specify IDs, a time window, or explicitly all_data=true')
    def inside(self,dt):return dt is not None and dt<=self.cutoff and (not self.start or self.start<=dt<self.end)
    def threshold(self,k):
        v=self.e.get(k)
        if v is not None and (isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) or v<=0):raise ValueError(k+' must be finite and positive')
        return v
    def result(self,domain,metrics,details,**extra):
        return dict(status='complete',complete=True,read_only=True,domain=domain,kn_id=self.knid,snapshot_at=self.now.isoformat(),as_of=self.cutoff.isoformat(),time_window={'start_inclusive':self.e.get('start_time'),'end_exclusive':self.e.get('end_time'),'timezone':'Asia/Shanghai'},metrics=metrics,details=details[:self.limit],detail_count=len(details),details_truncated=len(details)>self.limit,calls=self.calls,basis='当前授权身份可见resource；多次只读查询不构成事务快照。快照指标不能回溯历史状态。',**extra)

def order_journey(e):
    b=Biz(e);b.scope('order_ids');threshold=b.threshold('wait_threshold_hours')
    rows=b.scan('SELECT log_id,order_id,from_status,to_status,operator_type,operator_id,remark,created_at FROM '+b.table('order_status_log')+where([in_filter('order_id',ids(e,'order_ids'))])+' ORDER BY order_id,created_at,log_id')
    groups=defaultdict(list)
    for r in rows:
        dt=moment(r['created_at'])
        if dt and dt<=b.cutoff:groups[r['order_id']].append(r)
    details=[];durations=[];cancelled=set();refunds=set();duplicates=noops=0
    for oid,rs in groups.items():
        seen=set();timeline=[];episodes=[];state=None;entered=None;paid=shipped=None;gaps=0
        for r in rs:
            dt=moment(r['created_at']);key=(r['from_status'],r['to_status'],dt)
            if key in seen:duplicates+=1;continue
            seen.add(key)
            if r['from_status']==r['to_status']:noops+=1;continue
            if state is not None and r['from_status']==state and entered:
                episodes.append({'state':state,'entered_at':entered.isoformat(),'left_at':dt.isoformat(),'hours':elapsed(entered,dt)})
            elif state is not None and r['from_status']!=state:gaps+=1
            state=r['to_status'];entered=dt
            if (r['from_status'],state)==('pending_payment','pending_delivery') and paid is None:paid=dt
            if (r['from_status'],state)==('pending_delivery','shipped') and shipped is None:shipped=dt
            if b.inside(dt) and (r['from_status'],state)==('pending_delivery','cancelled'):cancelled.add(oid)
            if b.inside(dt) and (r['from_status'],state)==('shipped','refunding'):refunds.add(oid)
            timeline.append({'log_id':r['log_id'],'from_status':r['from_status'],'to_status':state,'time':dt.isoformat(),'operator_type':r['operator_type'],'operator_id':r['operator_id']})
        h=elapsed(paid,shipped)
        if h is not None and b.inside(shipped):durations.append(h)
        waiting=elapsed(entered,b.cutoff) if state not in {'completed','cancelled','refunded'} else None
        if b.start and not any(b.inside(moment(x['time'])) for x in timeline):continue
        details.append({'order_id':oid,'state_at_cutoff':state,'current_state_wait_hours':waiting,'attention':waiting>threshold if waiting is not None and threshold is not None else None,'paid_to_first_ship_hours':h,'episodes':episodes,'timeline':timeline,'sequence_gaps':gaps})
    return b.result('order_journey',[metric('M01','付款至首次发货平均耗时',average(durations),'h',sample_size=len(durations),time_basis='首次发货时间'),metric('M02','付款后待发货阶段取消订单数',len(cancelled),time_basis='取消迁移时间'),metric('M03','已发货阶段转入退款订单数',len(refunds),time_basis='转入退款迁移时间')],details,excluded_duplicate_events=duplicates,ignored_same_state_events=noops,wait_threshold_hours=threshold)

def logistics(e):
    b=Biz(e);b.scope('order_ids','shipment_ids');threshold=b.threshold('stagnation_hours')
    f=[in_filter('s.order_id',ids(e,'order_ids')),in_filter('s.shipment_id',ids(e,'shipment_ids'))]
    carriers=e.get('carriers',[])
    if not isinstance(carriers,list) or len(carriers)>50 or any(not isinstance(x,str) for x in carriers):raise ValueError('carriers must be a string array')
    if carriers:f.append('s.express_company IN ('+','.join(literal(x) for x in carriers)+')')
    rows=b.scan('SELECT s.shipment_id,s.order_id,s.express_company,s.warehouse_id,s.shipped_at,t.tracking_id,t.tracking_status,t.tracked_at,t.location,t.description FROM '+b.table('shipment')+' s LEFT JOIN '+b.table('logistics_tracking')+' t ON s.shipment_id=t.shipment_id'+where(f)+' ORDER BY s.shipment_id,t.tracked_at,t.tracking_id')
    groups=defaultdict(list)
    for r in rows:
        if moment(r['shipped_at']) is not None and moment(r['shipped_at'])<=b.cutoff:groups[r['shipment_id']].append(r)
    details=[];hours=[];bycarrier=defaultdict(list);open_count=0;bad=0
    for sid,rs in groups.items():
        nodes=[r for r in rs if r['tracked_at'] and moment(r['tracked_at'])<=b.cutoff]
        pickup=next((moment(r['tracked_at']) for r in nodes if r['tracking_status']=='已揽件'),None)
        signed=next((moment(r['tracked_at']) for r in nodes if r['tracking_status']=='已签收'),None)
        h=elapsed(pickup,signed);latest=nodes[-1] if nodes else None;status=latest['tracking_status'] if latest else '无轨迹'
        terminal=status in {'已签收','已退回','取消发货'}
        since=elapsed(moment(latest['tracked_at']) if latest else moment(rs[0]['shipped_at']),b.cutoff)
        if pickup and signed and h is None:bad+=1
        if h is not None and b.inside(signed):hours.append(h);bycarrier[rs[0]['express_company']].append(h)
        if not terminal:open_count+=1
        if b.start and not any(b.inside(moment(r['tracked_at'])) for r in nodes):continue
        details.append({'shipment_id':sid,'order_id':rs[0]['order_id'],'carrier':rs[0]['express_company'],'warehouse_id':rs[0]['warehouse_id'],'status':status,'pickup_at':pickup.isoformat() if pickup else None,'signed_at':signed.isoformat() if signed else None,'transport_hours':h,'hours_since_last_update':since,'attention':(since>threshold and not terminal) if since is not None and threshold is not None else None,'timeline':[{'tracking_id':r['tracking_id'],'status':r['tracking_status'],'time':r['tracked_at'],'location':r['location']} for r in nodes]})
    return b.result('logistics',[metric('M04','揽收至签收平均耗时',average(hours),'h',sample_size=len(hours),time_basis='首次签收时间')],details,open_shipments=open_count,invalid_time_pairs=bad,by_carrier=[{'carrier':k,'sample_size':len(v),'avg_hours':average(v)} for k,v in bycarrier.items()],stagnation_hours=threshold)

def cart_demand(e):
    if e.get('as_of') or e.get('start_time') or e.get('end_time'):raise ValueError('Cart analysis is a current snapshot; historical windows are not supported')
    b=Biz(e);b.scope('user_ids','sku_ids');f=[in_filter('c.user_id',ids(e,'user_ids')),in_filter('i.sku_id',ids(e,'sku_ids'))]
    if e.get('selected_only',False):f.append('i.is_selected=1')
    rows=b.scan('SELECT i.item_id,i.cart_id,c.user_id,i.sku_id,i.quantity,i.is_selected,s.product_id,s.status AS sku_status,p.status AS product_status,p.unit,s.stock_quantity,s.alert_quantity FROM '+b.table('cart_item')+' i JOIN '+b.table('cart')+' c ON i.cart_id=c.cart_id JOIN '+b.table('product_sku')+' s ON i.sku_id=s.sku_id JOIN '+b.table('product')+' p ON s.product_id=p.product_id'+where(f)+' ORDER BY i.item_id')
    holds=b.scan('SELECT sku_id,SUM(quantity) AS qty FROM '+b.table('inventory_quality_hold')+' GROUP BY sku_id ORDER BY sku_id')
    reserves=b.scan('SELECT sku_id,SUM(reserved_quantity) AS qty FROM '+b.table('inventory_reservation')+" WHERE status='active' GROUP BY sku_id ORDER BY sku_id")
    hm={r['sku_id']:int(r['qty']) for r in holds};rm={r['sku_id']:int(r['qty']) for r in reserves};carts=set();affected=set();gs={}
    for r in rows:
        sid=r['sku_id'];carts.add(r['cart_id']);off=r['sku_status']!='active' or r['product_status']!='online'
        if off:affected.add(r['cart_id'])
        g=gs.setdefault(sid,{'sku_id':sid,'product_id':r['product_id'],'unit':r['unit'],'cart_ids':set(),'user_ids':set(),'quantity':0,'selected_quantity':0,'off_sale':off,'physical_quantity':int(r['stock_quantity']),'held_quantity':hm.get(sid,0),'reserved_quantity':rm.get(sid,0)})
        g['cart_ids'].add(r['cart_id']);g['user_ids'].add(r['user_id']);g['quantity']+=int(r['quantity']);g['selected_quantity']+=int(r['quantity']) if r['is_selected']==1 else 0
    details=[];series=[]
    for g in gs.values():
        g['cart_count']=len(g.pop('cart_ids'));g['user_count']=len(g.pop('user_ids'));g['available_quantity']=g['physical_quantity']-g['held_quantity']-g['reserved_quantity'];g['intent_exceeds_available_by']=max(g['quantity']-g['available_quantity'],0)
        details.append(g);series.append({'sku_id':g['sku_id'],'value':g['quantity'],'unit':g['unit']})
    details.sort(key=lambda x:(not x['off_sale'],-x['intent_exceeds_available_by'],-x['user_count'],x['sku_id']))
    return b.result('cart_demand',[metric('M05','购物车下架商品影响率',ratio(len(affected),len(carts)),numerator=len(affected),denominator=len(carts),time_basis='当前快照'),metric('M06','SKU购物车保留需求量',None,status='grouped',group_by=['sku_id'],groups=series,time_basis='当前快照')],details,nonempty_cart_count=len(carts),affected_cart_count=len(affected),sku_count=len(gs),selected_only=e.get('selected_only',False),interpretation='意向需求并非已成交需求或采购指令；可售口径复用实物-隔离-active预占，不扣待补量。')

def payment_retry(e):
    b=Biz(e);b.scope('order_ids')
    rows=b.scan('SELECT attempt_id,order_id,attempt_no,channel,status,amount,attempted_at,settled_at,failure_code FROM '+b.table('payment_attempt')+where([in_filter('order_id',ids(e,'order_ids'))])+' ORDER BY order_id,attempt_no,attempt_id')
    groups=defaultdict(list)
    for r in rows:
        dt=moment(r['attempted_at'])
        if dt and dt<=b.cutoff:groups[r['order_id']].append(r)
    channels=e.get('channels',[]);codes=e.get('failure_codes',[])
    if any(not isinstance(v,list) or len(v)>50 or any(not isinstance(x,str) for x in v) for v in [channels,codes]):raise ValueError('channels and failure_codes must be string arrays')
    total=failed=recovered=0;details=[];bychannel=defaultdict(lambda:{'orders':0,'first_failed':0,'recovered':0});invalid=0
    for oid,rs in groups.items():
        if len({r['attempt_no'] for r in rs})!=len(rs):raise ValueError('Duplicate order/attempt_no; refusing ambiguous first attempt')
        first=rs[0]
        if not b.inside(moment(first['attempted_at'])) or channels and first['channel'] not in channels:continue
        if any(moment(y['attempted_at'])<moment(x['attempted_at']) for x,y in zip(rs,rs[1:])):invalid+=1;continue
        total+=1;isfailed=first['status']=='failed';failed+=int(isfailed)
        successes=[r for r in rs[1:] if r['status']=='success' and (moment(r['settled_at']) or moment(r['attempted_at']))<=b.cutoff]
        success=successes[0] if isfailed and successes else None;recovered+=int(success is not None)
        g=bychannel[first['channel']];g['orders']+=1;g['first_failed']+=int(isfailed);g['recovered']+=int(success is not None)
        if not codes or first['failure_code'] in codes:details.append({'order_id':oid,'first_status':first['status'],'first_channel':first['channel'],'first_failure_code':first['failure_code'],'recovered':success is not None if isfailed else None,'recovery_hours':elapsed(moment(first['attempted_at']),moment(success['settled_at']) or moment(success['attempted_at'])) if success else None,'observation_hours':elapsed(moment(first['attempted_at']),b.cutoff),'attempts':rs})
    return b.result('payment_retry',[metric('M11','首次支付尝试失败率',ratio(failed,total),numerator=failed,denominator=total,time_basis='首次尝试时间'),metric('M12','首次支付失败恢复率',ratio(recovered,failed),numerator=recovered,denominator=failed,time_basis='首次尝试队列，恢复观察至as_of')],details,unrecovered_orders=failed-recovered,invalid_sequence_orders=invalid,by_channel=[dict(channel=k,**v) for k,v in bychannel.items()],detail_failure_code_filter=codes,cohort_note='failure_codes只筛选明细，不缩小首次失败率的分母。')

def activity_rules(e):
    b=Biz(e);b.scope('activity_ids')
    acts=b.scan('SELECT activity_id,activity_name,activity_type,status,start_time,end_time,priority FROM '+b.table('marketing_activity')+where([in_filter('activity_id',ids(e,'activity_ids'))])+' ORDER BY activity_id')
    aset={r['activity_id'] for r in acts};rules=b.scan('SELECT rule_id,activity_id,rule_type,rule_config,priority FROM '+b.table('activity_rule')+where([in_filter('activity_id',ids(e,'activity_ids'))])+' ORDER BY activity_id,priority,rule_id')
    labels={'tiered_discount':'阶梯减免','new_user_only':'新用户条件','group_min_size':'成团人数','buy_n_get_m':'买赠数量','flash_sale_stages':'活动时段','bargain_max_helpers':'助力人数及底价参数'}
    by=defaultdict(list)
    for r in rules:
        if r['activity_id'] not in aset:continue
        warnings=[]
        try:
            config=json.loads(r['rule_config'])
            if not isinstance(config,dict):warnings.append('配置不是JSON对象')
        except (ValueError,TypeError):config=None;warnings.append('配置无法解析为JSON')
        by[r['activity_id']].append({'rule_id':r['rule_id'],'rule_type':r['rule_type'],'meaning':labels.get(r['rule_type'],'尚未登记解释的规则类型'),'priority':r['priority'],'config':config,'warnings':warnings})
    details=[]
    for a in acts:
        rs=by[a['activity_id']];counts=defaultdict(int)
        for r in rs:counts[r['priority']]+=1
        details.append(dict(a,rules=rs,tied_priorities=[k for k,v in counts.items() if v>1],interpretation='优先级按数值列示；未假定执行方向、叠加顺序或并列即冲突。历史规则不等于当前可用优惠。'))
    return b.result('activity_rules',[],details)

def activity_config(e):
    b=Biz(e);b.scope('activity_ids','sku_ids')
    rows=b.scan('SELECT ap.ap_id,ap.activity_id,a.activity_name,a.status AS activity_status,a.start_time,a.end_time,ap.sku_id,ap.product_id,ap.activity_price,ap.stock_quantity,ap.sold_quantity,ap.per_user_limit,s.price AS current_price,s.cost_price AS current_cost,p.unit FROM '+b.table('activity_product')+' ap JOIN '+b.table('marketing_activity')+' a ON ap.activity_id=a.activity_id JOIN '+b.table('product_sku')+' s ON ap.sku_id=s.sku_id JOIN '+b.table('product')+' p ON ap.product_id=p.product_id'+where([in_filter('ap.activity_id',ids(e,'activity_ids')),in_filter('ap.sku_id',ids(e,'sku_ids'))])+' ORDER BY ap.ap_id')
    below=above=0
    for r in rows:
        r['below_current_cost']=dec(r['activity_price'])<dec(r['current_cost']);r['above_current_sale']=dec(r['activity_price'])>dec(r['current_price']);below+=int(r['below_current_cost']);above+=int(r['above_current_sale']);r['comparison_basis']='历史活动价与当前SKU价格/成本的跨时点对照，不证明历史亏损';r['stock_basis']='源记录活动库存；初始配额/剩余量未证实，不计算售罄率'
    return b.result('activity_config',[],rows,below_current_cost_rows=below,above_current_sale_rows=above)

def procurement_progress(e):
    b=Biz(e);poids=ids(e,'po_item_ids',100);skus=ids(e,'sku_ids',500)
    reservations=b.scan('SELECT reservation_id,order_id,item_id,sku_id,po_item_id,ordered_quantity,reserved_quantity,backorder_quantity,status FROM '+b.table('inventory_reservation')+where(["status='active'",in_filter('sku_id',skus)])+' ORDER BY reservation_id')
    if poids:reservations=[r for r in reservations if r['po_item_id'] in poids]
    requested=set(poids)|{r['po_item_id'] for r in reservations if r['po_item_id'] is not None}
    rows=b.scan('SELECT i.item_id,i.po_id,i.sku_id,i.quantity,i.received_qty,p.order_status,p.expected_date FROM '+b.table('purchase_order_item')+' i JOIN '+b.table('purchase_order')+' p ON i.po_id=p.po_id'+where([in_filter('i.item_id',sorted(requested))])+' ORDER BY i.item_id') if requested else []
    ledger=b.scan('SELECT po_item_id,SUM(quantity) AS qty FROM '+b.table('inbound_record')+where([in_filter('po_item_id',sorted(requested))])+' GROUP BY po_item_id ORDER BY po_item_id') if requested else []
    received={r['po_item_id']:int(r['qty']) for r in ledger};details=[]
    for r in rows:
        r['ledger_received_qty']=received.get(r['item_id'],0);r['remaining_qty']=max(int(r['quantity'])-r['ledger_received_qty'],0);r['snapshot_matches_ledger']=int(r['received_qty'])==r['ledger_received_qty'];due=moment(r['expected_date']);r['due_state']='unknown' if due is None else 'overdue_unreceived' if due.date()<b.cutoff.date() and r['remaining_qty']>0 else 'not_overdue';r['related_reservations']=[x for x in reservations if x['po_item_id']==r['item_id']];details.append(r)
    active=[r for r in reservations if int(r['ordered_quantity'])>0];full=sum(int(r['reserved_quantity'])>=int(r['ordered_quantity']) for r in active);short={r['order_id'] for r in active if int(r['backorder_quantity'])>0}
    return b.result('procurement_progress',[metric('M07','当前缺货待补订单数',len(short),time_basis='当前预占快照'),metric('M08','库存预占足量订单行占比',ratio(full,len(active)),numerator=full,denominator=len(active),time_basis='当前预占快照')],details,reservations=reservations,scope={'sku_ids':skus,'po_item_ids':poids},date_note='当前入库事实对照观察日；缺预计日期为unknown，不回算历史收货快照。')

def aftersales_timing(e):
    b=Biz(e);b.scope('order_ids','case_ids')
    rows=b.scan('SELECT case_id,order_id,business_type,status,requested_amount,approved_amount,refund_amount,requested_at,approved_at,return_received_at,completed_at FROM '+b.table('after_sales_case')+where([in_filter('case_id',ids(e,'case_ids',100)),in_filter('order_id',ids(e,'order_ids',100))])+' ORDER BY case_id')
    threshold=b.threshold('wait_threshold_hours');groups=defaultdict(list);details=[];pending=Decimal(0);count=0;invalid=0
    for r in rows:
        start=moment(r['requested_at']);end=moment(r['completed_at']);h=elapsed(start,end)
        if end is not None and h is None:invalid+=1
        if h is not None and b.inside(end):groups[r['business_type']].append(h)
        # Current outstanding request amount is a snapshot, independent of the completed-event window.
        if end is None and start and start<=b.now:pending+=dec(r['requested_amount']);count+=1
        r['completed_hours']=h;r['current_wait_hours']=elapsed(start,b.now) if end is None else None;r['attention']=r['current_wait_hours']>threshold if r['current_wait_hours'] is not None and threshold is not None else None;details.append(r)
    series=[{'business_type':k,'value':average(v),'sample_size':len(v)} for k,v in groups.items()]
