def sqltime(dt):return literal(dt.strftime('%Y-%m-%d %H:%M:%S.%f'))
def order_journey(e):
    b=Biz(e);b.scope('order_ids');b.threshold('wait_threshold_hours')
    event_window='created_at<='+sqltime(b.cutoff)
    if b.start:event_window+=' AND created_at>='+sqltime(b.start)+' AND created_at<'+sqltime(b.end)
    sql="SELECT order_id,MIN(CASE WHEN from_status='pending_payment' AND to_status='pending_delivery' THEN created_at END) AS paid_at,MIN(CASE WHEN from_status='pending_delivery' AND to_status='shipped' THEN created_at END) AS shipped_at,MAX(CASE WHEN from_status='pending_delivery' AND to_status='cancelled' AND "+event_window+" THEN 1 ELSE 0 END) AS paid_cancel,MAX(CASE WHEN from_status='shipped' AND to_status='refunding' AND "+event_window+" THEN 1 ELSE 0 END) AS to_refund,SUM(CASE WHEN from_status=to_status THEN 1 ELSE 0 END) AS noops,MAX(created_at) AS latest_event FROM "+b.table('order_status_log')+where([in_filter('order_id',ids(e,'order_ids')),'created_at<='+sqltime(b.cutoff)])+' GROUP BY order_id ORDER BY order_id'
    states=['pending_payment','pending_delivery','shipped','completed','cancelled','refunding','refunded']
    state_fields=','.join("MAX(CASE WHEN to_status="+literal(s)+" AND (from_status IS NULL OR from_status<>to_status) THEN created_at END) AS entered_"+s for s in states)
    sql=sql.replace('SELECT order_id,','SELECT order_id,'+state_fields+",MAX(CASE WHEN "+event_window+" THEN 1 ELSE 0 END) AS has_window_event,",1)
    rows=b.scan(sql);hours=[];cancelled=refunds=0;eligible=[]
    for r in rows:
        h=elapsed(moment(r['paid_at']),moment(r['shipped_at']))
        if h is not None and b.inside(moment(r['shipped_at'])):hours.append(h)
        cancelled+=int(r['paid_cancel']);refunds+=int(r['to_refund'])
        if not b.start or r['has_window_event']:
            entries=[(moment(r['entered_'+s]),s) for s in states if r['entered_'+s]]
            latest,state=max(entries) if entries else (None,'unknown')
            active=state not in {'completed','cancelled','refunded','unknown'}
            eligible.append((not active,latest or b.cutoff,r['order_id']))
    eligible.sort();chosen=[x[2] for x in eligible[:b.limit]];detail=_order_journey_full(dict(e,order_ids=chosen,all_data=False,as_of=b.cutoff.isoformat())) if chosen else None
    out=b.result('order_journey',[metric('M01','付款至首次发货平均耗时',average(hours),'h',sample_size=len(hours),time_basis='首次发货时间'),metric('M02','付款后待发货阶段取消订单数',cancelled,time_basis='取消迁移时间'),metric('M03','已发货阶段转入退款订单数',refunds,time_basis='转入退款迁移时间')],detail['details'] if detail else [],ignored_same_state_events=sum(int(r['noops']) for r in rows),eligible_order_count=len(eligible),wait_threshold_hours=e.get('wait_threshold_hours'))
    if detail:out['calls']+=detail['calls'];out['detailed_duplicate_events']=detail['excluded_duplicate_events']
    out['details_truncated']=len(eligible)>len(out['details']);return out

def logistics(e):
    b=Biz(e);b.scope('order_ids','shipment_ids');b.threshold('stagnation_hours')
    f=[in_filter('order_id',ids(e,'order_ids')),in_filter('shipment_id',ids(e,'shipment_ids'))]
    carriers=e.get('carriers',[])
    if not isinstance(carriers,list) or len(carriers)>50 or any(not isinstance(x,str) for x in carriers):raise ValueError('carriers must be a string array')
    if carriers:f.append('express_company IN ('+','.join(literal(x) for x in carriers)+')')
    ships=b.scan('SELECT shipment_id,order_id,express_company,warehouse_id,shipped_at FROM '+b.table('shipment')+where(f)+' ORDER BY shipment_id')
    sm={r['shipment_id']:r for r in ships if moment(r['shipped_at']) and moment(r['shipped_at'])<=b.cutoff}
    if not sm:return b.result('logistics',[metric('M04','揽收至签收平均耗时',None,'h',sample_size=0)],[])
    event_window='tracked_at<='+sqltime(b.cutoff)
    if b.start:event_window+=' AND tracked_at>='+sqltime(b.start)+' AND tracked_at<'+sqltime(b.end)
    rows=b.scan("SELECT shipment_id,MIN(CASE WHEN tracking_status='已揽件' THEN tracked_at END) AS pickup_at,MIN(CASE WHEN tracking_status='已签收' THEN tracked_at END) AS signed_at,MAX(CASE WHEN tracking_status IN ('已签收','已退回','取消发货') THEN tracked_at END) AS last_terminal,MAX(tracked_at) AS last_node,MAX(CASE WHEN "+event_window+" THEN 1 ELSE 0 END) AS has_window_event FROM "+b.table('logistics_tracking')+where(['tracked_at<='+sqltime(b.cutoff),in_filter('shipment_id',sorted(sm)) if len(sm)<=1000 else ''])+' GROUP BY shipment_id ORDER BY shipment_id')
    hours=[];by=defaultdict(list);eligible=[];seen=set();open_count=invalid=0
    for r in rows:
        sid=r['shipment_id']
        if sid not in sm:continue
        seen.add(sid);pickup=moment(r['pickup_at']);signed=moment(r['signed_at']);h=elapsed(pickup,signed)
        if pickup and signed and h is None:invalid+=1
        if h is not None and b.inside(signed):hours.append(h);by[sm[sid]['express_company']].append(h)
        if r['last_terminal'] is None or moment(r['last_terminal'])<moment(r['last_node']):open_count+=1
        if not b.start or r['has_window_event']:
            terminal=r['last_terminal'] is not None and moment(r['last_terminal'])>=moment(r['last_node'])
            eligible.append((terminal,moment(r['last_node']),sid))
    eligible.sort();chosen=[x[2] for x in eligible[:b.limit]];detail=_logistics_full(dict(e,shipment_ids=chosen,all_data=False,as_of=b.cutoff.isoformat())) if chosen else None
    out=b.result('logistics',[metric('M04','揽收至签收平均耗时',average(hours),'h',sample_size=len(hours),time_basis='首次签收时间')],detail['details'] if detail else [],by_carrier=[{'carrier':k,'sample_size':len(v),'avg_hours':average(v)} for k,v in by.items()],invalid_time_pairs=invalid,open_shipments_at_cutoff=open_count+len(set(sm)-seen),no_nodes_at_cutoff=len(set(sm)-seen),eligible_shipment_count=len(eligible),stagnation_hours=e.get('stagnation_hours'))
    if detail:out['calls']+=detail['calls']
    out['details_truncated']=len(eligible)>len(out['details']);return out


