import json,math,re
from datetime import datetime,timezone,timedelta
from decimal import Decimal
from collections import defaultdict
from bkn_osdk import kn

TZ=timezone(timedelta(hours=8))
def moment(v):
    if v is None or v=='':return None
    if not isinstance(v,str):raise ValueError('Date/time must be ISO8601 text')
    d=datetime.fromisoformat(v.replace('Z','+00:00'))
    return d.replace(tzinfo=TZ) if d.tzinfo is None else d.astimezone(TZ)
def dec(v):return Decimal(str(v)) if v is not None else Decimal(0)
def ids(e,k,maximum=1000):
    v=e.get(k,[])
    if not isinstance(v,list) or len(v)>maximum:raise ValueError(k+' must be an array with at most '+str(maximum)+' IDs')
    if any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or int(x)!=x or x<=0 for x in v):raise ValueError(k+' must contain positive integer IDs')
    return sorted(set(map(int,v)))
def literal(v):return "'"+str(v).replace("'","''")+"'"
def in_filter(column,values):return column+' IN ('+','.join(map(str,values))+')' if values else ''
def where(parts):return ' WHERE '+' AND '.join('('+s+')' for s in parts if s) if any(parts) else ''
def metric(code,name,value,unit='1',**kw):return dict(code=code,name=name,value=value,unit=unit,status=kw.pop('status','no_data' if value is None else 'ok'),**kw)
def ratio(n,d):return n/d if d else None
def average(xs):return sum(xs)/len(xs) if xs else None
def elapsed(a,b):return (b-a).total_seconds()/3600 if a is not None and b is not None and b>=a else None

class Biz:
    def __init__(self,e):
        if not isinstance(e,dict):raise ValueError('Input must be an object')
        self.e=e;self.knid=e.get('kn_id')
        if not isinstance(self.knid,str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,100}',self.knid):raise ValueError('kn_id is required')
        self.now=datetime.now(TZ);self.cutoff=moment(e.get('as_of')) or self.now
        self.start=moment(e.get('start_time'));self.end=moment(e.get('end_time'))
        if bool(self.start)!=bool(self.end) or self.start and self.start>=self.end:raise ValueError('Provide a valid start_time/end_time pair')
        if self.end and self.end>self.cutoff:raise ValueError('end_time must not exceed as_of')
        self.limit=e.get('detail_limit',20)
        if isinstance(self.limit,bool) or not isinstance(self.limit,int) or not 0<=self.limit<=100:raise ValueError('detail_limit must be an integer from 0 to 100')
        for k in ['all_data','selected_only']:
            if k in e and not isinstance(e[k],bool):raise ValueError(k+' must be boolean')
        self.calls=[];self.ctx=kn.resolve_context()
        network=self.request('/api/bkn-backend/v1/knowledge-networks/'+self.knid,query={'mode':'export'})
        self.objects={o['id']:o for o in network.get('object_types',[])}
    def request(self,path,body=None,query=None):return kn.request(self.ctx,path,method='POST' if body is not None else 'GET',body=body,query=query,timeout=25)
    def table(self,oid):
        o=self.objects.get(oid);s=(o or {}).get('data_source',{})
        if s.get('type')!='resource' or not re.fullmatch(r'[a-zA-Z0-9_-]+',s.get('id','')):raise ValueError('Missing resource binding: '+oid)
        return '{{'+s['id']+'}}'
    def scan(self,sql):
        rows=[]
        for off in range(0,250000,5000):
            r=self.request('/api/vega-backend/v1/resources/query',{'query':sql,'query_format':'sql','paging':{'mode':'single','limit':5000,'offset':off}})
            if not isinstance(r,dict) or not isinstance(r.get('entries'),list) or r.get('warnings'):raise ValueError('Incomplete or invalid resource response')
            batch=r['entries'];rows.extend(batch)
            if len(batch)<5000:
                self.calls.append({'kind':'resource_sql','query':sql,'rows':len(rows),'pages':off//5000+1});return rows
        raise ValueError('250000-row safety bound reached; no partial totals returned')
    def scope(self,*keys):
