            if b.inside(dt) and (r['from_status'],state)==('shipped','refunding'):refunds.add(oid)
            timeline.append({'log_id':r['log_id'],'from_status':r['from_status'],'to_status':state,'time':dt.isoformat(),'operator_type':r['operator_type'],'operator_id':r['operator_id']})
        h=elapsed(paid,shipped)
        if h is not None and b.inside(shipped):durations.append(h)
        waiting=elapsed(entered,b.cutoff) if state not in {'completed','cancelled','refunded'} else None
        if b.start and not any(b.inside(moment(x['time'])) for x in timeline):continue
        details.append({'order_id':oid,'state_at_cutoff':state,'current_state_wait_hours':waiting,'attention':waiting>threshold if waiting is not None and threshold is not None else None,'paid_to_first_ship_hours':h,'episodes':episodes,'timeline':timeline,'sequence_gaps':gaps})
