    holds=b.scan('SELECT sku_id,SUM(quantity) AS qty FROM '+b.table('inventory_quality_hold')+' GROUP BY sku_id ORDER BY sku_id')
    reserves=b.scan('SELECT sku_id,SUM(reserved_quantity) AS qty FROM '+b.table('inventory_reservation')+" WHERE status='active' GROUP BY sku_id ORDER BY sku_id")
    hm={r['sku_id']:int(r['qty']) for r in holds};rm={r['sku_id']:int(r['qty']) for r in reserves};carts=set();affected=set();gs={}
    for r in rows:
        sid=r['sku_id'];carts.add(r['cart_id']);off=r['sku_status']!='active' or r['product_status']!='online'
        if off:affected.add(r['cart_id'])
        g=gs.setdefault(sid,{'sku_id':sid,'product_id':r['product_id'],'unit':r['unit'],'cart_ids':set(),'user_ids':set(),'quantity':0,'selected_quantity':0,'off_sale':off,'physical_quantity':int(r['stock_quantity']),'held_quantity':hm.get(sid,0),'reserved_quantity':rm.get(sid,0)})
        g['cart_ids'].add(r['cart_id']);g['user_ids'].add(r['user_id']);g['quantity']+=int(r['quantity']);g['selected_quantity']+=int(r['quantity']) if r['is_selected']==1 else 0
    details=[];series=[]
    for g in gs.values():
        g['cart_count']=len(g.pop('cart_ids'));g['user_count']=len(g.pop('user_ids'));g['available_quantity']=g['physical_quantity']-g['held_quantity']-g['reserved_quantity'];g['intent_exceeds_available_by']=max(g['quantity']-g['available_quantity'],0)
        details.append(g);series.append({'sku_id':g['sku_id'],'value':g['quantity'],'unit':g['unit']})
    details.sort(key=lambda x:(not x['off_sale'],-x['intent_exceeds_available_by'],-x['user_count'],x['sku_id']))
    return b.result('cart_demand',[metric('M05','购物车下架商品影响率',ratio(len(affected),len(carts)),numerator=len(affected),denominator=len(carts),time_basis='当前快照'),metric('M06','SKU购物车保留需求量',None,status='grouped',group_by=['sku_id'],groups=series,time_basis='当前快照')],details,nonempty_cart_count=len(carts),affected_cart_count=len(affected),sku_count=len(gs),selected_only=e.get('selected_only',False),interpretation='意向需求并非已成交需求或采购指令；可售口径复用实物-隔离-active预占，不扣待补量。')

def payment_retry(e):
    b=Biz(e);b.scope('order_ids')
    rows=b.scan('SELECT attempt_id,order_id,attempt_no,channel,status,amount,attempted_at,settled_at,failure_code FROM '+b.table('payment_attempt')+where([in_filter('order_id',ids(e,'order_ids'))])+' ORDER BY order_id,attempt_no,attempt_id')
    groups=defaultdict(list)
    for r in rows:
        dt=moment(r['attempted_at'])
