TZ=timezone(timedelta(hours=8))
def parse(value):
    if value is None or not str(value).strip():return None
    text=str(value).strip()
    if len(text)==10:return date.fromisoformat(text)
    dt=datetime.fromisoformat(text.replace('Z','+00:00'))
    if dt.tzinfo is None:dt=dt.replace(tzinfo=TZ)
    return dt.astimezone(TZ).date()
def handler(event):
    expected=parse(event.get('expected_date'));actual=parse(event.get('actual_date'))
    if expected is None or actual is None:return {'on_time':None,'delay_days':None,'status':'unknown','timezone':'Asia/Shanghai'}
    delay=max((actual-expected).days,0)
    return {'on_time':actual<=expected,'delay_days':delay,'status':'on_time' if actual<=expected else 'delayed','timezone':'Asia/Shanghai'}

