def scan(sql):
    rows=[]
    for offset in range(0,250000,5000):
        response=kn.request(kn.resolve_context(),'/api/vega-backend/v1/resources/query',method='POST',body={'query':sql,'query_format':'sql','paging':{'mode':'single','limit':5000,'offset':offset}})
        if not isinstance(response,dict) or 'entries' not in response:
            raise ValueError('Source query did not return a table')
        if response.get('warnings'):raise ValueError('Source query returned warnings; refusing incomplete totals')
        page=response['entries'];rows.extend(page)
        if len(page)<5000:return rows
    raise ValueError('Scan exceeded 250000 rows; refusing incomplete totals')

def handler(event):
    raw=event.get('sku_ids') or []
    if not isinstance(raw,list) or len(raw)>1000:raise ValueError('sku_ids must contain at most 1000 IDs')
    ids=[]
    for x in raw:
        if isinstance(x,bool) or int(x)!=x or int(x)<=0:raise ValueError('SKU IDs must be positive integers')
        ids.append(int(x))
    online=event.get('online_only',True)
    if not isinstance(online,bool):raise ValueError('online_only must be boolean')
    limit=event.get('detail_limit',20)
    if isinstance(limit,bool) or int(limit)!=limit or not 0<=limit<=1000:raise ValueError('detail_limit must be between 0 and 1000')
    limit=int(limit)
    def table(name):return '{{'+RESOURCES[name]+'}}'
    conditions=[]
    if online:conditions.append("p.status='online' AND s.status='active'")
    if ids:conditions.append('s.sku_id IN ('+','.join(map(str,ids))+')')
    sql='SELECT s.sku_id,s.product_id,p.brand_id,b.brand_name,s.stock_quantity,s.alert_quantity FROM '+table('product_sku')+' s JOIN '+table('product')+' p ON s.product_id=p.product_id LEFT JOIN '+table('brand')+' b ON p.brand_id=b.brand_id'
    if conditions:sql+=' WHERE '+' AND '.join(conditions)
    sku_rows=scan(sql+' ORDER BY s.sku_id')
    if len({r['sku_id'] for r in sku_rows})!=len(sku_rows):raise ValueError('Duplicate SKU identity in source join')
    suffix=(' WHERE sku_id IN ('+','.join(map(str,ids))+')') if ids else ''
    holds=scan('SELECT sku_id,SUM(quantity) AS qty FROM '+table('inventory_quality_hold')+suffix+' GROUP BY sku_id ORDER BY sku_id')
    reservations=scan('SELECT sku_id,SUM(reserved_quantity) AS qty FROM '+table('inventory_reservation')+" WHERE status='active'"+(' AND sku_id IN ('+','.join(map(str,ids))+')' if ids else '')+' GROUP BY sku_id ORDER BY sku_id')
    held={r['sku_id']:int(r['qty'] or 0) for r in holds};reserved={r['sku_id']:int(r['qty'] or 0) for r in reservations}
    groups={};details=[];below=at=0
    for r in sku_rows:
        sid=r['sku_id'];physical=int(r['stock_quantity']);h=held.get(sid,0);v=reserved.get(sid,0);available=physical-h-v;alert=int(r['alert_quantity'])
        below+=int(available<alert);at+=int(available<=alert)
        group=groups.setdefault(r['brand_id'],{'brand_id':r['brand_id'],'brand_name':r['brand_name'],'sku_count':0,'below_alert_count':0,'at_or_below_alert_count':0})
        group['sku_count']+=1;group['below_alert_count']+=int(available<alert);group['at_or_below_alert_count']+=int(available<=alert)
        details.append({'sku_id':sid,'product_id':r['product_id'],'physical_quantity':physical,'held_quantity':h,'reserved_quantity':v,'available_quantity':available,'alert_quantity':alert})
    details.sort(key=lambda x:(x['available_quantity'],x['sku_id']))
    return {'sku_count':len(sku_rows),'below_alert_count':below,'at_or_below_alert_count':at,'by_brand':list(groups.values()),'details':details[:limit],'details_truncated':len(details)>limit,'complete':True,'online_only':online,'basis':'源表当前可见数据；可售=实物-隔离-active实际预占；待补不重复扣减。多个只读查询不构成数据库事务快照。'}

