                if not high.is_finite() or not medium.is_finite() or not high>medium>=0:raise ValueError('user segmentation requires finite high > medium >= 0 thresholds')
        if DOMAIN=='inventory' and not sku_ids and not args.all_skus:raise ValueError('provide --sku-ids or explicitly --all-skus')
        if sku_ids and args.all_skus:raise ValueError('do not combine --sku-ids and --all-skus')
        if not 0<=args.detail_limit<=1000:raise ValueError('detail limit must be 0 to 1000')
        if args.user_id is not None and args.user_id<=0:raise ValueError('user ID must be positive')
        if DOMAIN=='coupon' and not any([order_ids,template_ids,case_ids,args.user_id,args.check_validity]):raise ValueError('provide coupon/aftersales scope or --check-validity')
    except (ValueError,ArithmeticError) as e:raise ValueError(str(e)) from None
    ctx=kn.resolve_context();base='/api/bkn-backend/v1/knowledge-networks/'+args.kn_id
    def request(path,method='GET',body=None,query=None):
        return kn.request(ctx,path,method=method,body=body,query=query,timeout=120)
    caps=request(base+'/capabilities',query={'limit':500})
    if len(caps.get('entries',[]))!=caps.get('total_count'):raise ValueError('Capability discovery is incomplete')
    deps=DEPS
    allowed=set(deps['function_names']);warnings=[];results={};calls=[]
    def function(name,params):
        if name not in allowed:raise ValueError('Function not allowed by this skill')
        matches=[e for e in caps['entries'] if e.get('name')==name and e['capability_type']=='function']
        if len(matches)!=1:raise ValueError('Missing or ambiguous mounted function: '+name)
        f=matches[0]
        out=request('/api/agent-operator-integration/v1/tool-box/'+f['box_id']+'/proxy/'+f['capability_id'],'POST',{'body':params,'header':{},'query':{},'path':{}})
        if out.get('status_code')!=200:raise ValueError('Function proxy failed: '+name)
        body=out.get('body') or {}
        if body.get('exit_code',0)!=0 or body.get('stderr'):raise ValueError('Function execution failed: '+name+' '+str(body.get('stderr',''))[:300])
        result=body.get('result',body)
        if isinstance(result,dict) and (result.get('complete') is False or result.get('limited') is True or result.get('warnings')):warnings.append(name+': incomplete result')
        results[name]=result;calls.append({'type':'function','name':name,'id':f['capability_id'],'box_id':f['box_id']})
        return result
    templates={q['name']:q for q in QUERIES}
